import java.io.*;
import java.util.*;
import java.util.stream.IntStream;

public class TwentyFive {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();

        int matches = 0;

        // Precompute pattern length
        int patternLen = s.length();

        // Iterate only through multiples of 25 up to 99,999,975
        for (int value = 0; value < 100_000_000; value += 25) {
            String candidate = Integer.toString(value);

            if (candidate.length() != patternLen) continue;

            char xRep = 0;
            boolean foundX = false;
            boolean matchesPattern = true;

            for (int idx = 0; idx < patternLen; idx++) {
                char pChar = s.charAt(idx);
                char cChar = candidate.charAt(idx);

                if (pChar == 'X') {
                    if (!foundX) {
                        xRep = cChar;
                        foundX = true;
                    } else if (cChar != xRep) {
                        matchesPattern = false;
                        break;
                    }
                } else if (pChar != '_') {
                    if (cChar != pChar) {
                        matchesPattern = false;
                        break;
                    }
                }
            }

            if (matchesPattern) matches++;
        }

        System.out.println(matches);
    }
}
